        import re
        regex_trips = [t.upper() for t in re.findall(r"\bT\d{5,7}\b", text, re.IGNORECASE)]

        dm_match = re.search(r"\b(?:september|sept|sep)\s*(\d{1,2})(?:st|nd|rd|th)?\b", text, re.IGNORECASE)
